{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C23"],
      "claim": "Benazeprilat, the closest structural analogue (Morgan 0.7544), reached 27.1–28.5% absolute oral bioavailability only when generated from the ester prodrug benazepril; this high value reflects prodrug absorption and does not transfer to the query's non-prodrug free-acid/amine form.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C32"],
      "claim": "Benazepril itself has oral bioavailability of 28–37%, but it is the ethyl ester prodrug; the query lacks this ester moiety, so the high F is not applicable to the more polar, fully ionized free-acid/amine query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C27"],
      "claim": "Olcegepant, a highly polar peptide-like molecule with multiple ionizable groups, has absolute oral bioavailability <1%, providing affirmative evidence that extensive ionization and polarity can drive F below 20%; this supports low for the query's fully ionized, high-TPSA structure despite modest structural similarity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Lysine has 79% systemic availability in humans via transporter-mediated absorption, but the query is an N-substituted lysine derivative with a bulky benzazepinone on the alpha nitrogen, so this high-absorption pathway is unlikely to transfer.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low: the query is a highly ionized, polar free-acid/amine lysine-conjugated benzazepinone with very low estimated logD and full ionization at pH 7.4. The closest high-F analogues (benazeprilat/benazepril) owe their oral absorption to ester prodrug forms, which the query lacks; the only direct low-F analogue (olcegepant) supports poor permeability for highly polar structures. Transporter-mediated high absorption of lysine is unlikely due to N-substitution.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the exact query or a close non-prodrug free-acid analogue.",
    "No data on active transport (e.g., amino acid transporters) or efflux for the query.",
    "No human PK data for the lysine-conjugated benzazepinone scaffold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

